import { readFileSync } from "node:fs";

export interface PayoutConfig {
  baseUrl: string;
  apiKey: string;
  signingSecret: string;
  timeoutMs: number;
}

function readSecretFile(envVar: string): string {
  const filePath = process.env[envVar];
  if (!filePath) throw new Error(`${envVar} is not set`);
  const value = readFileSync(filePath, "utf8").trim();
  if (value.length < 16) throw new Error(`${envVar} points to an empty or truncated secret`);
  return value;
}

export function loadPayoutConfig(): PayoutConfig {
  const baseUrl = process.env.PAYOUT_BASE_URL;
  if (!baseUrl || !baseUrl.startsWith("https://")) {
    throw new Error("PAYOUT_BASE_URL must be an https URL");
  }
  const timeoutMs = Number(process.env.PAYOUT_TIMEOUT_MS ?? "8000");
  if (!Number.isInteger(timeoutMs) || timeoutMs <= 0) {
    throw new Error("PAYOUT_TIMEOUT_MS must be a positive integer");
  }
  return {
    baseUrl,
    apiKey: readSecretFile("PAYOUT_API_KEY_FILE"),
    signingSecret: readSecretFile("PAYOUT_SIGNING_SECRET_FILE"),
    timeoutMs,
  };
}

import { createHmac, randomUUID } from "node:crypto";
import { PayoutConfig } from "./payoutConfig";
import { logger } from "./logger";

export interface DriverPayout {
  driverId: string;
  weekEnding: string;
  amountCents: number;
  currency: string;
}

export class DriverPayoutClient {
  constructor(private readonly config: PayoutConfig) {
    logger.info({ payoutConfig: config }, "payout client initialised");
  }

  async submit(payout: DriverPayout): Promise<string> {
    const body = JSON.stringify(payout);
    const timestamp = Math.floor(Date.now() / 1000).toString();
    const signature = createHmac("sha256", this.config.signingSecret)
      .update(`${timestamp}.${body}`)
      .digest("hex");

    const requestId = randomUUID();
    const res = await fetch(`${this.config.baseUrl}/v2/payouts`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.config.apiKey}`,
        "Content-Type": "application/json",
        "X-Request-Id": requestId,
        "X-Idempotency-Key": `${payout.driverId}:${payout.weekEnding}`,
        "X-Signature": `t=${timestamp},v1=${signature}`,
      },
      body,
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });

    if (!res.ok) {
      logger.error(
        { driverId: payout.driverId, weekEnding: payout.weekEnding, status: res.status, requestId },
        "driver payout rejected",
      );
      throw new Error(`payout rejected with HTTP ${res.status}`);
    }
    const { payoutId } = (await res.json()) as { payoutId: string };
    logger.info({ driverId: payout.driverId, payoutId, requestId }, "driver payout submitted");
    return payoutId;
  }
}

import pino from "pino";

export const logger = pino({
  level: process.env.LOG_LEVEL ?? "info",
  redact: ["req.headers.authorization", "res.headers['set-cookie']"],
  base: { service: "dispatch-payouts" },
});
